mapper.select:
SELECT m.id, m.type, m.title, m.content, m.link, m.publisher_id, COALESCE(NULLIF(p.nickname, ''), p.account, '系统') AS publisher_name, m.status, m.scheduled_at, m.error_msg, m.create_time, COUNT(r.id) AS recipient_count, COUNT(r.id) FILTER (WHERE r.read_at IS NOT NULL) AS read_count, COUNT(r.id) FILTER (WHERE r.read_at IS NULL) AS unread_count FROM sys_message m LEFT JOIN sys_user p ON p.id = m.publisher_id AND p.deleted = 0 LEFT JOIN sys_message_recipient r ON r.message_id = m.id
m.deleted = 0
AND m.title ILIKE CONCAT('%', #{query.title}, '%')
AND m.type = #{query.type}
AND m.status = #{query.status}
AND m.create_time >= #{query.createTimeStart}
AND m.create_time <= #{query.createTimeEnd}
GROUP BY m.id, p.nickname, p.account ORDER BY m.create_time DESC, m.id DESC
